-- 仅供角色变更影响预览集成测试。租户 A 中一个 Tenant Admin 与多种状态的成员，租户 B 用于跨租户访问，租户 C 用于超出 Plan 的场景。插入须可重复执行。
ON CONFLICT DO NOTHING;
SELECT v.id, v.account, v.account || '@example.com', v.display_name, i.password_hash
FROM identity i CROSS JOIN (VALUES
    (CAST('019a0120-0000-7000-8000-000000000101' AS uuid), 'impactadmin', '影响管理员'),
    (CAST('019a0120-0000-7000-8000-000000000102' AS uuid), 'impactsolo', '仅目标角色'),
    (CAST('019a0120-0000-7000-8000-000000000103' AS uuid), 'impactdual', '另有角色'),
    (CAST('019a0120-0000-7000-8000-000000000104' AS uuid), 'impactbuiltin', '兼任管理员'),
    (CAST('019a0120-0000-7000-8000-000000000105' AS uuid), 'impactsuspended', '已停用'),
    (CAST('019a0120-0000-7000-8000-000000000106' AS uuid), 'impactinvited', '已邀请'),
    (CAST('019a0120-0000-7000-8000-000000000107' AS uuid), 'impactplain', '无管理权限'),
    (CAST('019a0120-0000-7000-8000-000000000108' AS uuid), 'impactadminb', '租户 B 管理员'),
    (CAST('019a0120-0000-7000-8000-000000000109' AS uuid), 'impactadminc', '租户 C 管理员'),
    (CAST('019a0120-0000-7000-8000-00000000010a' AS uuid), 'impactmemberc', '租户 C 成员')
) AS v (id, account, display_name)
WHERE i.account = 'demo' ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
-- 前 20 名的场景需要超过 20 个成员，账号按序号补零，标识顺序即期望顺序。
